module fifo(input clk,input rst_n,input wr_en,rd_en,input[7:0] din,output reg[7:0] dout,output full,empty);reg[7:0] m[0:3];reg[1:0] w,r;reg[2:0] n;assign full=n==4;assign empty=n==0;always@(posedge clk)if(!rst_n)begin w<=0;r<=0;n<=0;dout<=0;end else begin case({wr_en&&!full,rd_en&&!empty})2'b10:begin m[w]<=din;w<=w+1;n<=n+1;end 2'b01:begin dout<=m[r];r<=r+1;n<=n-1;end 2'b11:begin m[w]<=din;w<=w+1;dout<=m[r];r<=r+1;end default:begin end endcase end endmodule
